<?php
namespace App\Http\Controllers\Auth;
use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Http\RedirectResponse;use Illuminate\Support\Facades\Auth;use Illuminate\Validation\ValidationException;use Illuminate\View\View;
class LoginController extends Controller {public function create():View{return view('auth.login');}public function store(Request $request):RedirectResponse{$data=$request->validate(['email'=>'required|email','password'=>'required|string']);if(!Auth::attempt(['email'=>$data['email'],'password'=>$data['password'],'is_active'=>true],$request->boolean('remember'))){throw ValidationException::withMessages(['email'=>'Las credenciales no son válidas o la cuenta está inactiva.']);}$request->session()->regenerate();return redirect()->intended(route('dashboard'));}public function destroy(Request $request):RedirectResponse{Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect()->route('login')->with('success','Sesión cerrada.');}}
